  "content.c1": "অ্যাক্সেসিবিলিটির পরিচিতি",
  "content.c1d": "WCAG গাইডলাইন, সহায়ক প্রযুক্তি, এবং অন্তর্ভুক্তিমূলক ডিজাইনের মূল ভিত্তি কভার করে একটি বিস্তৃত কোর্স।",
