  "content.c3": "ব্রেইল সাক্ষরতার বেসিকস",
  "content.c3d": "শুরুর দিকের শিক্ষার্থীদের জন্য কাঠামোবদ্ধ পাঠের মাধ্যমে ব্রেইল পড়া ও লেখা শুরু করুন।",
  "content.c4": "অ্যাডাপটিভ টেকনোলজি ওয়ার্কশপ",
  "content.c4d": "ম্যাগনিফায়ার, ভয়েস অ্যাসিস্ট্যান্ট, এবং স্মার্ট অ্যাক্সেসিবিলিটি টুলস নিয়ে হাতে-কলমে প্রশিক্ষণ।",
  "content.a1": "অ্যাক্সেসিবিলিটি দিয়ে শুরু করুন",
  "content.a1d": "দিন এক থেকেই আপনার ডিজিটাল জীবনকে আরও অ্যাক্সেসযোগ্য করার জন্য অপরিহার্য টিপস।",
  "content.a2": "রঙের কনট্রাস্টের সেরা অনুশীলন",
  "content.a2d": "ঠিকমতো রঙের কনট্রাস্ট কিভাবে সবার জন্য পড়ার সুবিধা বাড়ায়।",
  "content.a3": "কীবোর্ড নেভিগেশন প্যাটার্ন",
  "content.a3d": "দ্রুত ব্রাউজিংয়ের জন্য কীবোর্ড শর্টকাট ও ট্যাব নেভিগেশন আয়ত্ত করুন।",
  "content.a4": "অন্তর্ভুক্তিমূলক ডিজাইন নীতিমালা",
  "content.a4d": "যেখানে অ্যাক্সেসিবিলিটিকে কেন্দ্রে রাখা হয় এমন ডিজাইন থিংকিং কৌশল।",
  "content.a5": "ARIA লেবেল সঠিকভাবে করা",
  "content.a5d": "অর্থবহ ARIA অ্যাট্রিবিউট এবং স্ক্রিন রিডার সাপোর্টের জন্য একটি ডেভেলপার গাইড।",
  "content.p1": "আজকের অ্যাক্সেসিবিলিটি",
  "content.p1d": "অ্যাক্সেসিবিলিটি অ্যাডভোকেট, টেক লিডার, এবং ব্যবহারকারীদের সাথে সাপ্তাহিক আলোচনা।",
  "content.p2": "অন্তর্ভুক্তিমূলক কণ্ঠস্বর",
  "content.p2d": "বিশ্বজুড়ে দৃষ্টিপ্রতিবন্ধী ব্যক্তিদের গল্প ও অভিজ্ঞতা।",
  "content.p3": "বাধাহীন প্রযুক্তি",
  "content.p3d": "কীভাবে উদীয়মান প্রযুক্তি প্রতিবন্ধী মানুষের জন্য বাধা কমাচ্ছে তা অন্বেষণ।",
  "content.m1": "অডিও বর্ণিত ডকুমেন্টারি",
  "content.m1d": "মুগ্ধকর অভিজ্ঞতার জন্য সম্পূর্ণ অডিও বর্ণনাসহ ডকুমেন্টারি।",
  "content.m2": "সাইন ল্যাঙ্গুয়েজ টিউটোরিয়াল",
  "content.m2d": "ক্যাপশনসহ, উচ্চ কনট্রাস্টের ভিডিও পাঠ দিয়ে সাইন ল্যাঙ্গুয়েজ শিখুন।",
