  "legal.access.commitment1": "অ্যাক্সেসিবিলিটি Visionex-এর মিশনের কেন্দ্রে। আমাদের প্ল্যাটফর্মটি ভিজ্যুয়াল প্রতিবন্ধকতা, শ্রবণগত পার্থক্য, মোটর প্রতিবন্ধকতা, জ্ঞানগত পার্থক্য, এবং অন্যান্য অ্যাক্সেস চাহিদাসম্পন্ন ব্যবহারকারীদের পাশাপাশি সব অন্যান্য ব্যবহারকারীকেও সহায়তা করার জন্য ডিজাইন করা হয়েছে। যুক্তিসঙ্গতভাবে সম্ভব হলে আমরা WCAG 2.1 Level AA-এর সাথে সামঞ্জস্য আনার লক্ষ্য রাখি।",
  "legal.access.commitment2": "আমরা বিশ্বাস করি, ডিজিটাল অ্যাক্সেসিবিলিটি হলো একটি অন্তর্ভুক্তিমূলক প্ল্যাটফর্ম অভিজ্ঞতার অপরিহার্য অংশ। আমরা ডেভেলপমেন্টের সময় অ্যাক্সেসিবিলিটি মূল্যায়ন করি এবং রিলিজের পরও ফিচার উন্নত করতে থাকি।",
