  "jungle.scene6": "আপনি একটি আহত পাখি খুঁজে পান। আপনি কী করবেন?",
  "jungle.s6c1": "সাবধানে বহন করুন — এটা হয়তো আপনাকে পথ দেখাবে (+5 HP, +25 pts)",
  "jungle.s6c2": "ওকে ফেলে যান — যত্ন নিতে শক্তি নষ্ট হবে (0 HP, +10 pts)",
  "jungle.scene7": "একটি নদী আপনার পথ আটকে দিয়েছে। পানি দ্রুত মনে হচ্ছে।",
  "jungle.s7c1": "পড়ে থাকা লগ দিয়ে ভেলা বানান (−5 HP, +40 pts)",
  "jungle.s7c2": "অল্প গভীর পারাপার খুঁজতে স্রোতের উজানে হাঁটুন (+10 HP, +20 pts)",
  "jungle.scene8": "দূরে ধোঁয়া দেখতে পান।",
  "jungle.s8c1": "ধোঁয়ার দিকে এগোন — উদ্ধার হতে পারে! (+15 HP, +45 pts)",
  "jungle.s8c2": "এড়িয়ে চলুন — এটা হয়তো বন্য আগুন (−5 HP, +15 pts)",
  "jungle.scene9": "রাত নেমে আসছে। আপনার আশ্রয় দরকার।",
  "jungle.s9c1": "শিকারিদের থেকে নিরাপদ থাকতে একটি লম্বা গাছে উঠুন (+10 HP, +30 pts)",
  "jungle.s9c2": "ডালপালা দিয়ে মাটির নিচের আশ্রয় বানান (−5 HP, +35 pts)",
  "jungle.scene10": "আপনি এমন একটি ফল পান যা চিনতে পারছেন না। আপনি খুব ক্ষুধার্ত।",
  "jungle.s10c1": "খেয়ে ফেলুন — আপনি তো মরতে বসেছেন! (−20 HP, +30 pts)",
  "jungle.s10c2": "প্রথমে আপনার ত্বকে অল্প অংশ পরীক্ষা করুন (0 HP, +20 pts)",
  "jungle.scene11": "পথের উপর একটি বড় সাপ পেঁচিয়ে আছে।",
  "jungle.s11c1": "ধীরে ধীরে পিছিয়ে যান এবং ঘুরপথ খুঁজুন (+5 HP, +30 pts)",
  "jungle.s11c2": "ওকে ভয় দেখিয়ে দূরে সরানোর চেষ্টা করুন (−25 HP, +40 pts)",
  "jungle.scene12": "আপনি একটি জলপ্রপাত শুনতে পান — আপনার পানির সরবরাহ খুবই কম।",
  "jungle.s12c1": "নতুন পানি খুঁজতে শব্দ অনুসরণ করুন (+20 HP, +35 pts)",
  "jungle.s12c2": "এড়িয়ে যান এবং সামনে এগোতে থাকুন (−15 HP, +20 pts)",
  "jungle.scene13": "হঠাৎ করে ঝড় এসে পড়ছে।",
  "jungle.s13c1": "উঁচু জায়গা খুঁজে কভার নিন (+10 HP, +25 pts)",
  "jungle.s13c2": "এ থেকে পালাতে এগিয়ে যান (−10 HP, +30 pts)",
  "jungle.scene14": "আপনি একটি গুহা খুঁজে পান। অন্ধকার হয়ে আসছে।",
  "jungle.s14c1": "আশ্রয়ের জন্য গুহায় ঢুকুন (+15 HP, +30 pts)",
  "jungle.s14c2": "গাছের নিচে ঘুমান — গুহায় কেউ থাকতে পারে (+5 HP, +20 pts)",
  "jungle.scene15": "আপনি ক্লান্ত। সামনে একটি ফাঁকা জায়গা নিরাপদ মনে হচ্ছে।",
  "jungle.s15c1": "বিশ্রাম নিন ও সুস্থ হন (+20 HP, +20 pts)",
  "jungle.s15c2": "চলতেই থাকুন — এখানে বিশ্রাম বিপজ্জনক (−5 HP, +30 pts)",
  "jungle.scene16": "আপনি একটি গাছে খোদাই করা পুরনো মানচিত্র খুঁজে পান।",
  "jungle.s16c1": "মানচিত্রের দিক অনুসরণ করুন (+5 HP, +40 pts)",
  "jungle.s16c2": "এটা এড়িয়ে যান — হয়তো পুরনো হয়ে গেছে (0 HP, +10 pts)",
  "jungle.scene17": "বন্য শুয়োরগুলো আগ্রাসিভাবে আপনার পথ আটকে দিচ্ছে।",
  "jungle.s17c1": "দ্রুত কাছের গাছে উঠুন (+5 HP, +30 pts)",
  "jungle.s17c2": "জায়গায় দাঁড়িয়ে চিৎকার করুন (−20 HP, +35 pts)",
  "jungle.scene18": "আপনি সরবরাহসহ একটি পরিত্যক্ত শিবির খুঁজে পান।",
  "jungle.s18c1": "যা কিছু কাজে লাগে সব নিন (+20 HP, +50 pts)",
  "jungle.s18c2": "ওটা ফেলে যান — পরে কারও দরকার হতে পারে (0 HP, +10 pts)",
  "jungle.scene19": "একটি বানর আপনার খাবারের ব্যাগ চুরি করে!",
  "jungle.s19c1": "বানরটাকে তাড়া করুন (−10 HP, +40 pts)",
  "jungle.s19c2": "ছেড়ে দিন — শক্তি নষ্ট করা সার্থক নয় (+0 HP, +15 pts)",
  "jungle.scene20": "আপনি মাথার উপর একটি হেলিকপ্টার শুনতে পান।",
  "jungle.s20c1": "এখনই সংকেতের আগুন জ্বালান! (+30 HP, +60 pts)",
  "jungle.s20c2": "হাত নাড়ান — এটা হয়তো আপনাকে দেখবে (+5 HP, +40 pts)",
  "tactical.combo": "🔥 কম্বো ×{n}!",
  "tactical.gift": "🎁 বোনাস টার্গেট!",
  "tactical.howTo.1": "🎯 টার্গেটে ট্যাপ করুন +10 পয়েন্টের জন্য",
  "tactical.howTo.2": "⭐ তে ট্যাপ করুন +25 pts, 🎁 তে +75 pts",
  "tactical.howTo.3": "💣 এড়িয়ে চলুন — এগুলোর খরচ −15 পয়েন্ট এবং কম্বো রিসেট করে",
  "tactical.howTo.4": "পরপর ৩+টি টার্গেটে আঘাত করুন কম্বোর গুণক পেতে!",
