  "starchef.wrongIngredient": "ভুল উপকরণ! −10 pts",
  "starchef.clearPlate": "প্লেট পরিষ্কার করুন",
  "starchef.ordersServed": "পরিবেশিত",
  "starchef.howTo.1": "উপরের অর্ডার কার্ডটা সাবধানে পড়ুন",
  "starchef.howTo.2": "ডিশ বানাতে মিলছে এমন উপকরণে ট্যাপ করুন",
  "starchef.howTo.3": "ভুল উপকরণে −10 pts খরচ হয়",
  "starchef.howTo.4": "ভুল করলে Clear Plate সব উপকরণ সরিয়ে দেয়",
  "starchef.howTo.5": "সময় শেষ হওয়ার আগে যতটা সম্ভব সঠিক অর্ডার পরিবেশন করুন",
  "akinator.q.arab": "এই চরিত্র কি আরব বা ইসলামি বিশ্বের?",
  "akinator.q.sports": "এই ব্যক্তি কি বিখ্যাত কোনো ক্রীড়াবিদ?",
  "akinator.q.scientist": "এই ব্যক্তি কি একজন বিজ্ঞানী বা উদ্ভাবক?",
