  "akinator.char.saladin": "সালাদিন",
  "akinator.char.rumi": "রুমি",
  "akinator.char.avicenna": "আভিসেনা (ইবন সিনা)",
  "akinator.char.muhammadAli": "মুহাম্মদ আলী",
  "akinator.char.ronaldo": "ক্রিস্টিয়ানো রোনালদো",
  "akinator.char.messi": "লিওনেল মেসি",
  "akinator.howTo.1": "কোনো বাস্তব বা কাল্পনিক চরিত্রের কথা ভাবুন",
  "akinator.howTo.2": "প্রশ্নগুলোর উত্তর সৎভাবে দিন (Yes/Probably/Don't Know/Probably Not/No)",
  "akinator.howTo.3": "প্রতিটি উত্তরের সাথে AI প্রার্থীদের সংখ্যা কমিয়ে আনে",
  "akinator.howTo.4": "Akinator কি ২০টি প্রশ্নের মধ্যে আপনার চরিত্রটা ধরতে পারে দেখুন!",
  "neonbreach.howTo.1": "জ্বলা নোডগুলোর ক্রমটা মনোযোগ দিয়ে দেখুন",
  "neonbreach.howTo.2": "তারপর ট্যাপ করে একই ক্রম আবার করুন",
  "neonbreach.howTo.3": "প্রতিটি সঠিক লেভেল মনে রাখার জন্য আরও একটি নোড যোগ করে",
  "neonbreach.howTo.4": "একটা ভুল ট্যাপ করলেই ফায়ারওয়াল আপনাকে ধরবে!",
  "earmaster.howTo.1": "যে মিউজিক নোট বাজছে সেটা মনোযোগ দিয়ে শুনুন",
  "earmaster.howTo.2": "৭টি অপশন থেকে আপনি যে নোট শুনেছেন সেটি বেছে নিন",
  "earmaster.howTo.3": "নোটটা একবার আবার শুনতে Play বোতাম ব্যবহার করুন",
  "earmaster.howTo.4": "চূড়ান্ত স্কোর দেখতে ১০টি রাউন্ড সম্পূর্ণ করুন",
  "uno.howTo.1": "রং বা সংখ্যার ভিত্তিতে স্তূপের উপরের কার্ডের সাথে মিল করুন",
  "uno.howTo.2": "বাজাতে আপনার হাতে থাকা একটি কার্ডে ট্যাপ করুন",
  "uno.howTo.3": "যদি কোনো মিল না থাকে, কার্ড যোগ করতে Draw-এ ট্যাপ করুন",
  "uno.howTo.4": "হাতের সব কার্ড আগে খালি করতে পারলেই জয়!",
  "briscola.howTo.1": "ব্রিস্কোলা হলো একটি ইতালীয় ট্রিক-টেকিং কার্ড খেলা",
  "briscola.howTo.2": "ট্রাম্প স্যুট (ব্রিস্কোলা) সব অন্য স্যুটকে হারায়",
  "briscola.howTo.3": "ট্রিক জিতে পয়েন্ট সংগ্রহ করুন — Ace=11, 3=10, King=4, Queen=3, Jack=2",
  "briscola.howTo.4": "সব কার্ড খেলার পর সর্বোচ্চ স্কোর হলে জয়",
  "card99.howTo.1": "কার্ড খেলুন যাতে চলমান টোটাল ৯৯-এর মধ্যে বা কম থাকে",
  "card99.howTo.2": "বিশেষ কার্ড: King=0, Queen=hold, Jack=−10, Ace=1 অথবা 11",
  "card99.howTo.3": "টোটাল ৯৯-এর ওপরে নিয়ে গেলে আপনি একটি জীবন হারাবেন",
  "card99.howTo.4": "শেষ পর্যন্ত টিকে থাকা খেলোয়াড় (লাইফসহ) জয়ী!",
  "dominoes.howTo.1": "ডোমিনো চেইনের দুই প্রান্তের সংখ্যার সাথে মিলান",
  "dominoes.howTo.2": "আপনার হাতে থাকা টাইল থেকে ওপেন প্রান্তের সাথে মিল আছে এমন টাইল খেলুন",
  "dominoes.howTo.3": "খেলা না গেলে গাদা থেকে ড্র করুন",
  "dominoes.howTo.4": "যে আগে হাত খালি করবে (অথবা পিপের মোট কম) সে জয়ী!",
  "farkle.howTo.1": "৬টি ডাইস রোল করুন এবং যেসব ডাইস স্কোর করে সেগুলো আলাদা করে রাখুন",
  "farkle.howTo.2": "1s = 100 পয়েন্ট · 5s = 50 পয়েন্ট · Three-of-a-kind = মুখ= × 100",
  "farkle.howTo.3": "যদি রোলের পরে NO ডাইস স্কোর করে, তাহলে এটা হলো FARKLE — আপনার টার্ন হারাবেন!",
  "farkle.howTo.4": "পয়েন্ট ব্যাংক করুন যাতে সেগুলো থাকে, অথবা আরও ঝুঁকি/পুরস্কারের জন্য আবার রোল দিন",
  "quiz.howTo.1": "যত দ্রুত সম্ভব ২০টি মাল্টিপল-চয়েস প্রশ্নের উত্তর দিন",
  "quiz.howTo.2": "প্রতিটি প্রশ্নে ৩ সেকেন্ড — দ্রুত উত্তর দিন!",
  "quiz.howTo.3": "দ্রুত সঠিক উত্তর দিলে বেশি বোনাস পয়েন্ট পান",
  "quiz.howTo.4": "সব প্রশ্ন শেষ করে আপনার চূড়ান্ত র‌্যাঙ্ক দেখুন",
  "memory.howTo.1": "একবারে ২টি কার্ড উল্টান এবং মিলিয়ে জোড়া খুঁজুন",
  "memory.howTo.2": "মিললে সেগুলো উল্টো দিকেই থাকে",
  "memory.howTo.3": "মিল না হলে দুটোই আবার উল্টো করে নিচে নামান — মনে রাখুন কোথায় ছিল!",
  "memory.howTo.4": "যত কম মুভে সব জোড়া মিলিয়ে উচ্চ স্কোর করুন",
  "word.howTo.1": "জম্বল করা অক্ষরগুলো ঠিক করে সাজান যাতে লুকানো শব্দটি তৈরি হয়",
  "word.howTo.2": "উত্তর গঠনের জন্য অক্ষরগুলো সঠিক ক্রমে ট্যাপ করুন",
  "word.howTo.3": "আটকে গেলে Hint বোতাম ব্যবহার করুন (পয়েন্ট খরচ হবে)",
  "word.howTo.4": "পাজল শেষ করতে ৮টি শব্দ সম্পূর্ণ করুন",
