  "admin.academyHub.infoNote": "শিক্ষার্থী এবং তাদের অ্যানালিটিক্স সরাসরি Supabase ডাটাবেস থেকে পড়া হয় (সব ব্যবহারকারীর বাস্তব ডেটা)। কোর্স, সার্টিফিকেট এবং ইনস্ট্রাক্টরের ডেটা লোকালি তৈরি (পর্ব ৩–৬) হলেও তা প্রতিটি ব্যবহারকারীর নিজস্ব ব্রাউজারে সংরক্ষিত থাকে — তাই এটি এখানে বিস্তৃত তালিকা হিসেবে দেখা যায় না; এটি একটি বর্তমান স্থাপত্যগত সীমাবদ্ধতা, বাগ নয়, এবং এগুলো বাস্তব ডাটাবেজের সঙ্গে সংযুক্ত হলে সমাধান হবে।",
